// =============================================
// SPI Dual Mode Testbench - Auto-generated by SPI Customizer
// =============================================

`timescale 1ns / 1ps

module spi_dual_tb;

    // Parameters
    parameter MODE = 3;
    parameter DATA_WIDTH = 7;
    parameter NUM_SLAVES = 3;
    parameter SLAVE_ACTIVE_LOW = 1;
    parameter MSB_FIRST = 1;
    parameter FIFO_DEPTH = 16;
    parameter MAX_SLAVES = 8;
    parameter CLOCK_DIVIDER = 2;
    parameter DEFAULT_DATA_ENABLED = 0;
    parameter DEFAULT_DATA_VALUE = 7'he;

    // Signals
    reg clk;
    reg rst_n;
    reg master_mode;
    wire sclk;
    wire mosi;
    reg miso;
    wire [NUM_SLAVES-1:0] ss_n;
    reg sclk_in;
    reg mosi_in;
    wire miso_out;
    reg ss_in;
    reg [DATA_WIDTH-1:0] tx_data;
    wire [DATA_WIDTH-1:0] rx_data;
    wire rx_valid;
    wire tx_ready;
    reg tx_valid;
    wire busy;
    wire irq;

    // DUT instantiation
    spi_dual #(
        .MODE(MODE),
        .DATA_WIDTH(DATA_WIDTH),
        .NUM_SLAVES(NUM_SLAVES),
        .SLAVE_ACTIVE_LOW(SLAVE_ACTIVE_LOW),
        .MSB_FIRST(MSB_FIRST),
        .FIFO_DEPTH(FIFO_DEPTH),
        .MAX_SLAVES(MAX_SLAVES),
        .CLOCK_DIVIDER(CLOCK_DIVIDER),
        .DEFAULT_DATA_ENABLED(DEFAULT_DATA_ENABLED),
        .DEFAULT_DATA_VALUE(DEFAULT_DATA_VALUE)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .master_mode(master_mode),
        .sclk(sclk),
        .mosi(mosi),
        .miso(miso),
        .ss_n(ss_n),
        .sclk_in(sclk_in),
        .mosi_in(mosi_in),
        .miso_out(miso_out),
        .ss_in(ss_in),
        .rx_data(rx_data),
        .tx_data(tx_data),
        .rx_valid(rx_valid),
        .tx_ready(tx_ready),
        .tx_valid(tx_valid),
        .busy(busy),
        .irq(irq),
        .irq_clear(1'b0)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #10 clk = ~clk;  // 50MHz clock
    end

    // Test sequence for dual mode
    initial begin
        // Initialize
        rst_n = 0;
        master_mode = 1;  // Start in master mode
        tx_data = 0;
        tx_valid = 0;
        miso = 0;
        sclk_in = 0;
        mosi_in = 0;
        ss_in = 1;

        #100;
        rst_n = 1;
        #200;  // Allow system to stabilize

        $display("=== SPI Dual Mode RTL Testbench Starting ===");
        $display("Configuration: Mode %d, %d-bit data, Dual mode", MODE, DATA_WIDTH);

        // Test master mode first
        $display("--- Testing Master Mode ---");

        // Test basic transmission in master mode
        tx_data = 8'hA5;
        $display("TX Data: 0x%h", tx_data);

        // Wait for tx_ready, then start transmission
        @(posedge tx_ready);
        #10; // Small delay
        tx_valid = 1; // Assert tx_valid to start transmission
        #20; // Hold tx_valid for a few cycles
        tx_valid = 0; // Deassert tx_valid

        // Wait for transmission to complete with timeout
        fork
            begin
                @(negedge busy);
                $display("✓ Master transmission complete");
            end
            begin
                #10000; // 10us timeout
                $display("⚠️  Master transmission timeout - forcing completion");
                $finish;
            end
        join_any
        disable fork;

        // Switch to slave mode after master test
        #500;
        master_mode = 0;
        $display("--- Switched to Slave Mode ---");

        // Test slave mode with proper SPI master simulation
        #100;

        // Simulate a complete SPI transaction as master to our slave
        $display("Simulating SPI master transaction to test slave mode");

        // Start transaction: assert SS low
        ss_in = 0;
        $display("Slave selected (SS asserted low)");

        // SPI Mode 0: CPOL=0, CPHA=0
        // Data sampled on rising edge, changed on falling edge

        // Send test data (8'h5A = 01011010)
        mosi_in = 0; // Bit 7 (MSB first)
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 1; // Bit 6
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 0; // Bit 5
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 1; // Bit 4
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 1; // Bit 3
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 0; // Bit 2
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 1; // Bit 1
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        mosi_in = 0; // Bit 0 (LSB)
        sclk_in = 0; // Falling edge - change data
        #50; // Setup time
        sclk_in = 1; // Rising edge - sample bit
        #50; // Hold time

        // Return clock to idle
        sclk_in = 0;

        // End transaction: deassert SS
        #100;
        ss_in = 1;
        $display("✓ Slave mode SPI transaction complete - sent 0x5A");

        #200; // Allow slave to process

        $display("=== All Dual Mode Tests Completed Successfully ===");
        #100; // Small delay before finish
        $finish;
    end

    // VCD dumping
    initial begin
        $dumpfile("results/issue-48/data/spi_waveform.vcd");
        $dumpvars(0, spi_dual_tb);
    end

endmodule